using Xunit;

namespace Stride.Core.CompilerServices.Tests.GeneratorTests;

public class DerivedClassTests : UnifiedGeneratorTestBase
{
    [Fact]
    public async Task ScanningForBaseClass()
    {
        string testCode = """
            [Stride.Core.Reflection.AssemblyScan]
            public class BaseClass {}
            public class DerivedClass : BaseClass {}
            """;
        string expectedGeneratedCode = """
            // <auto-generated/>
            namespace Stride.Core.CompilerServices.AutoGenerated.ModuleInitializer
            {
                file static class ModuleInitializer
                {
                    [global::System.Runtime.CompilerServices.ModuleInitializer]
                    public static void Initialize()
                    {
                        global::Stride.Core.Serialization.AssemblyScan.AssemblyScanResults.Initialize();
                    }
                }
            }
            namespace Stride.Core.Serialization.AssemblyScan
            {
                file static partial class AssemblyScanResults
                {
                    [global::System.Diagnostics.CodeAnalysis.DynamicDependencyAttribute(global::System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicConstructors, typeof(global::BaseClass))]
                    [global::System.Diagnostics.CodeAnalysis.DynamicDependencyAttribute(global::System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicConstructors, typeof(global::DerivedClass))]
                    public static void Initialize()
                    {
                        global::Stride.Core.Reflection.AssemblyRegistry.RegisterScanTypes(
                            typeof(global::Stride.Core.Serialization.AssemblyScan.AssemblyScanResults).Assembly,
                            new global::Stride.Core.Reflection.AssemblyRegistry.ScanTypes(
                                new global::System.Collections.Generic.Dictionary<global::System.Type, global::System.Collections.Generic.List<global::System.Type>>
                                {
                                    {
                                        typeof(global::BaseClass),
                                        new global::System.Collections.Generic.List<global::System.Type> { typeof(global::BaseClass), typeof(global::DerivedClass), }
                                    },
            
                                }
                            )
                        );
                    }
                }
            }
            """;
        await TestGeneration(testCode, expectedGeneratedCode);
    }
}
